import {dailyDateForIdentity} from './daily-summary.mjs';
// Data-only daily puzzles. No downloaded code, network credentials, or campaign progress.
export const DAILY_SCHEMA=1, DAILY_RULESET='matter020-workshop-v1';
export const DAILY_LIMITS=Object.freeze({puzzleBytes:131072,indexBytes:131072,entries:400,cacheEntries:24,cacheBytes:2097152,blocks:10,screws:20});
const INDEX_KEY='screw-workshop-daily-index-v1',CACHE_KEY='screw-workshop-daily-cache-v1',PROGRESS_KEY='screw-workshop-daily-bests-v1';
const enc=new TextEncoder(),own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
const fail=m=>{throw new Error(m)};
const object=o=>!!o&&typeof o==='object'&&!Array.isArray(o)&&Object.getPrototypeOf(o)===Object.prototype;
function keys(o,allowed,required=[]){if(!object(o)||Object.keys(o).some(k=>!allowed.includes(k))||required.some(k=>!own(o,k)))fail('Unexpected or missing data fields');}
function text(s,max=240){if(typeof s!=='string'||!s.trim()||s.length>max||/[<>\u0000-\u001f]/.test(s))fail('Invalid plain text');return s;}
function id(s){if(typeof s!=='string'||!/^[a-z0-9][a-z0-9-]{0,79}$/.test(s))fail('Invalid puzzle ID');return s;}
function integer(n,min,max){if(!Number.isInteger(n)||n<min||n>max)fail('Invalid bounded integer');return n;}
export function utcDate(now=new Date()){const d=new Date(now);if(!Number.isFinite(d.getTime()))fail('Invalid date');return d.toISOString().slice(0,10);}
function date(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s)||utcDate(s+'T00:00:00Z')!==s)fail('Invalid challenge date');return s;}
function hash(s){if(typeof s!=='string'||!/^[a-f0-9]{64}$/.test(s))fail('Invalid SHA-256');return s;}
function coord(p){if(!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite)||p[0]<0||p[0]>350||p[1]<0||p[1]>430)fail('Invalid board coordinate');return p;}
function points(a,min,max){if(!Array.isArray(a)||a.length<min||a.length>max)fail('Invalid point count');a.forEach(coord);return a;}
function unique(a){if(new Set(a.map(p=>JSON.stringify(p))).size!==a.length)fail('Duplicate coordinates');}
function polygon(p){points(p,3,64);unique(p);let area=0;for(let i=0;i<p.length;i++){let q=p[(i+1)%p.length];area+=p[i][0]*q[1]-q[0]*p[i][1];}if(Math.abs(area)<.01)fail('Degenerate polygon');}
export function validateIndex(value){keys(value,['schemaVersion','rulesetVersion','entries'],['schemaVersion','rulesetVersion','entries']);if(value.schemaVersion!==DAILY_SCHEMA||value.rulesetVersion!==DAILY_RULESET)fail('Unsupported daily ruleset');if(!Array.isArray(value.entries)||value.entries.length>DAILY_LIMITS.entries)fail('Oversized daily index');const dates=new Set(),ids=new Set();for(const e of value.entries){keys(e,['date','id','url','sha256'],['date','id','url','sha256']);date(e.date);id(e.id);hash(e.sha256);if(typeof e.url!=='string'||! /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,119}\.json$/.test(e.url)||e.url.includes('..'))fail('Unsafe puzzle URL');if(dates.has(e.date)||ids.has(e.id))fail('Duplicate daily identity');dates.add(e.date);ids.add(e.id);}return structuredClone(value);}
export function validatePuzzle(value,{validateGeometry}={}){
 keys(value,['schemaVersion','rulesetVersion','id','name','recipe','targetMoves','witnessPolicy'],['schemaVersion','rulesetVersion','id','name','recipe','targetMoves','witnessPolicy']);
 if(value.schemaVersion!==DAILY_SCHEMA||value.rulesetVersion!==DAILY_RULESET||value.witnessPolicy!=='settle-after-each-move-2400')fail('Unsupported daily ruleset');id(value.id);text(value.name,80);
 const r=value.recipe;keys(r,['id','name','tip','rationale','pieces','plates','spareCount','spares','hidden','solution'],['id','name','tip','hidden','solution']);if(r.id!==value.id||r.name!==value.name)fail('Puzzle identity mismatch');text(r.tip);if(r.rationale!==undefined)text(r.rationale,500);if(!!r.pieces===!!r.plates)fail('Choose one geometry representation');
 const blocks=r.pieces||r.plates;integer(blocks?.length,1,DAILY_LIMITS.blocks);let anchors=[],vertices=0;
 for(const b of blocks){if(r.plates){points(b,2,2);anchors.push(...b);continue;}keys(b,['anchors','bar','outline','components','holes']);if(!!b.anchors===!!b.bar)fail('Choose one anchor representation');const pins=b.anchors||b.bar;points(pins,b.bar?2:1,b.bar?2:6);anchors.push(...pins);if(b.anchors&&!b.outline)fail('Custom piece needs outline');if(b.outline){polygon(b.outline);vertices+=b.outline.length;}if(b.components){if(!Array.isArray(b.components)||b.components.length<1||b.components.length>8)fail('Too many material components');for(const c of b.components){polygon(c);vertices+=c.length;}}if(b.holes){points(b.holes,0,12);unique(b.holes);}}
 integer(anchors.length,1,DAILY_LIMITS.screws);unique(anchors);if(vertices>1024)fail('Too many vertices');
 if(r.spares!==undefined&&r.spareCount!==undefined)fail('Choose one spare representation');if(r.spares!==undefined){points(r.spares,1,2);unique(r.spares);if(r.spares.some(p=>p[1]!==35))fail('Spare holes must use top rail');}else integer(r.spareCount,1,2);
 points(r.hidden,0,4);unique(r.hidden);const spares=r.spares||(r.spareCount===1?[[175,35]]:[[105,35],[245,35]]);unique([...anchors,...spares,...r.hidden]);
 if(!Array.isArray(r.solution))fail('Missing tested route');integer(r.solution.length,anchors.length,40);integer(value.targetMoves,1,40);if(value.targetMoves!==r.solution.length)fail('Target differs from tested route');const targets=new Set([...anchors,...spares,...r.hidden].map(p=>JSON.stringify(p))),released=new Set();for(const move of r.solution){if(!Array.isArray(move)||move.length!==2)fail('Invalid witness move');integer(move[0],0,anchors.length-1);coord(move[1]);if(!targets.has(JSON.stringify(move[1])))fail('Witness target is not a board hole');released.add(move[0]);}if(released.size!==anchors.length)fail('Witness does not release every original screw');
 // The caller supplies the real engine's bounded geometric checks before accepting data.
 if(typeof validateGeometry!=='function')fail('Daily geometry validator is required');validateGeometry(structuredClone(r));return structuredClone(value);
}
async function digest(raw,cryptoImpl){if(!cryptoImpl?.subtle)fail('Secure hashing unavailable');const bytes=await cryptoImpl.subtle.digest('SHA-256',enc.encode(raw));return [...new Uint8Array(bytes)].map(n=>n.toString(16).padStart(2,'0')).join('');}
function parse(raw,limit){if(typeof raw!=='string'||enc.encode(raw).length>limit)fail('Oversized JSON');return JSON.parse(raw);}
async function boundedText(response,limit){if(!response?.ok)fail('Daily download unavailable');const size=Number(response.headers?.get?.('content-length'));if(Number.isFinite(size)&&size>limit)fail('Oversized daily download');if(response.body?.getReader){const reader=response.body.getReader(),chunks=[];let size=0;for(;;){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>limit){await reader.cancel();fail('Oversized daily download');}chunks.push(value);}const bytes=new Uint8Array(size);let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length;}return new TextDecoder('utf-8',{fatal:true}).decode(bytes);}const raw=await response.text();if(enc.encode(raw).length>limit)fail('Oversized daily download');return raw;}
export function createDailyStore({baseURL,fetchImpl=globalThis.fetch,storage,cryptoImpl=globalThis.crypto,validateGeometry,fallbackPuzzle,networkEnabled=true,expectedOrigin=globalThis.location?.origin}={}){
 if(storage===undefined){try{storage=globalThis.localStorage}catch{storage=null}}
 const base=new URL(baseURL);if(base.username||base.password)fail('Daily base must not include credentials');if(networkEnabled&&expectedOrigin!==undefined&&base.origin!==expectedOrigin)fail('Daily base must be same-origin');if(!['https:','http:'].includes(base.protocol)&&!(base.protocol==='file:'&&!networkEnabled))fail('Daily base must be HTTP(S)');base.search='';base.hash='';if(!base.pathname.endsWith('/'))base.pathname+='/';
 let today=utcDate(),index={schemaVersion:DAILY_SCHEMA,rulesetVersion:DAILY_RULESET,entries:[]},cache={},indexPersisted=false;const fallback=validatePuzzle(fallbackPuzzle,{validateGeometry});
 const read=(k,limit)=>{try{return parse(storage?.getItem(k),limit)}catch{return null}};
 const save=(k,v)=>{try{if(typeof storage?.setItem!=='function')return false;storage.setItem(k,JSON.stringify(v));return true}catch{return false}};
 try{const old=read(INDEX_KEY,DAILY_LIMITS.indexBytes);if(old){index=validateIndex(old);indexPersisted=true;}}catch{}
 const oldCache=read(CACHE_KEY,DAILY_LIMITS.cacheBytes);if(object(oldCache))cache=Object.fromEntries(Object.entries(oldCache).slice(-DAILY_LIMITS.cacheEntries).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&object(v)&&typeof v.raw==='string'&&enc.encode(v.raw).length<=DAILY_LIMITS.puzzleBytes));
 function archive(){return index.entries.filter(e=>e.date<=today).sort((a,b)=>b.date.localeCompare(a.date)).map(e=>({...e}));}
 async function download(url,limit){if(!networkEnabled||typeof fetchImpl!=='function')fail('Daily downloads unavailable here');const timeout=new AbortController(),timer=setTimeout(()=>timeout.abort(),10000);try{const response=await fetchImpl(url,{credentials:'same-origin',cache:'no-cache',redirect:'error',signal:timeout.signal});return await boundedText(response,limit);}finally{clearTimeout(timer);}}
 async function refresh({now=new Date()}={}){today=utcDate(now);let error=null;try{const raw=await download(new URL('index.json',base).href,DAILY_LIMITS.indexBytes),next=validateIndex(parse(raw,DAILY_LIMITS.indexBytes));for(const old of index.entries){const replacement=next.entries.find(e=>e.date===old.date);if(replacement&&(old.id!==replacement.id||old.sha256!==replacement.sha256))fail('Published challenge identity changed');}const retained=index.entries.filter(e=>e.date<=today&&!next.entries.some(n=>n.date===e.date));index=validateIndex({...next,entries:[...next.entries,...retained]});indexPersisted=save(INDEX_KEY,index);if(!indexPersisted)error='Index loaded, but offline cache could not be saved.';}catch(e){error=e.message;}return {today,entries:archive(),error};}
 async function checked(raw,entry){if(await digest(raw,cryptoImpl)!==entry.sha256)fail('Daily checksum mismatch');const puzzle=validatePuzzle(parse(raw,DAILY_LIMITS.puzzleBytes),{validateGeometry});if(puzzle.id!==entry.id)fail('Daily identity mismatch');return puzzle;}
 async function fallbackResult(requested,error){return{date:requested,puzzle:structuredClone(fallback),recipe:structuredClone(fallback.recipe),identity:`fallback:${fallback.id}@${DAILY_RULESET}`,source:'fallback',error:error||'No published puzzle for this date; showing offline practice.'};}
 async function load(requested=today){date(requested);if(requested>today)fail('Future daily puzzle is not available');const entry=index.entries.find(e=>e.date===requested);let error=null;if(entry){try{const raw=await download(new URL(entry.url,base).href,DAILY_LIMITS.puzzleBytes),puzzle=await checked(raw,entry);cache[requested]={raw};const ordered=Object.keys(cache).sort();while(ordered.length>DAILY_LIMITS.cacheEntries||enc.encode(JSON.stringify(cache)).length>DAILY_LIMITS.cacheBytes)delete cache[ordered.shift()];const cached=save(CACHE_KEY,cache);return {date:requested,puzzle,recipe:puzzle.recipe,identity:`${entry.id}@${entry.sha256}`,source:'network',cacheSaved:cached&&indexPersisted,error:cached&&indexPersisted?null:'Puzzle loaded, but offline cache could not be saved.'};}catch(e){error=e.message;}
 try{const raw=cache[requested]?.raw;if(raw){const puzzle=await checked(raw,entry);return {date:requested,puzzle,recipe:puzzle.recipe,identity:`${entry.id}@${entry.sha256}`,source:'cache',error};}}catch(e){delete cache[requested];save(CACHE_KEY,cache);error=e.message;}}
 return fallbackResult(requested,error);}
 function validIdentity(k){return typeof k==='string'&&(/^[a-z0-9][a-z0-9-]{0,79}@[a-f0-9]{64}$/.test(k)||new RegExp('^fallback:[a-z0-9][a-z0-9-]{0,79}@'+DAILY_RULESET+'$').test(k))}
 let progressMemory={};
 function readProgress(){const value=read(PROGRESS_KEY,131072),out={};if(object(value))for(const[k,v]of Object.entries(value).slice(-500))if(validIdentity(k)&&Number.isInteger(v)&&v>0&&v<=100000)out[k]=v;for(const[k,v]of Object.entries(progressMemory))out[k]=Math.min(out[k]??Infinity,v);progressMemory={...out};return out;}
 function recordBest(identity,moves){if(!validIdentity(identity))fail('Invalid progress identity');integer(moves,1,100000);const bests=readProgress();bests[identity]=Math.min(bests[identity]??Infinity,moves);progressMemory={...bests};const entries=Object.entries(bests).slice(-500);if(!save(PROGRESS_KEY,Object.fromEntries(entries)))fail('Daily progress could not be saved');return bests[identity];}
 function recordCompletion(identity,moves){const date=dailyDateForIdentity(identity),bests=readProgress();const previous=Object.entries(bests).find(([id])=>id===identity||(date&&dailyDateForIdentity(id)===date));if(previous)return previous[1];return recordBest(identity,moves)}
 return {refresh,load,archive,readProgress,recordBest,recordCompletion};
}
